import type { Question } from "@/lib/types";

/* agile · scrum · devops · risk · people */
export const QUESTIONS_2: Question[] = [
  // agile-background
  { kind: "mc", id: "se-q-ab-1", concept: "agile-background", q: "애자일 방법이 등장한 시기는?", options: ["1960년대", "1970년대 초", "1990년대 후반", "2010년대"], answer: 2, explain: "== 정답: 1990년대 후반\n### 풀이\n애자일 방법은 **1990년대 후반**에 등장했어요(Emerged in the late 1990s). 2001년 애자일 선언문이 나왔어요." },
  { kind: "mc", id: "se-q-ab-2", concept: "agile-background", q: "애자일 개발의 특징이 아닌 것은?", options: ["명세·설계·구현이 교차", "잦은 새 버전 인도", "자동 테스트 같은 도구 지원", "포괄적이고 상세한 문서 작성"], answer: 3, explain: "== 정답: 포괄적이고 상세한 문서 작성\n### 왜 정답인가요\n애자일은 문서를 **최소한**으로 하고 **동작하는 코드**에 집중해요.\n### 다른 보기\n- 명세·설계·구현 교차, 잦은 새 버전 인도, 자동 테스트 등 도구 지원: 모두 애자일의 특징이에요." },
  { kind: "ox", id: "se-q-ab-3", concept: "agile-background", q: "애자일은 1980~90년대 설계 방법의 오버헤드에 대한 불만에서 생겨났다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n1980~90년대 설계 방법은 계획·문서 등 **오버헤드**가 너무 컸어요. 이 **불만**에서 애자일이 생겨났어요." },
  { kind: "ox", id: "se-q-ab-4", concept: "agile-background", q: "애자일 방법은 코드보다 설계에 집중한다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n애자일은 설계보다 **코드에 집중**해요(focus on the code rather than the design)." },
  { kind: "ox", id: "se-q-ab-5", concept: "agile-background", q: "빠르게 변하는 비즈니스 환경에서는 안정된 요구사항 집합을 만드는 것이 사실상 불가능하다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n비즈니스 환경이 빠르게 바뀌어서 **안정된 요구 집합을 만드는 건 사실상 불가능**해요. 그래서 **신속한 개발·인도**가 가장 중요한 요구가 됐어요." },

  // agile-manifesto
  { kind: "mc", id: "se-q-am-1", concept: "agile-manifesto", q: "애자일 선언문의 내용으로 옳은 것은?", options: ["프로세스와 도구 > 개인과 상호작용", "포괄적인 문서 > 동작하는 SW", "고객과의 협력 > 계약 협상", "계획을 따르기 > 변화에 대응"], answer: 2, explain: "== 정답: 고객과의 협력 > 계약 협상\n### 왜 정답인가요\n애자일 선언문 4줄(왼쪽을 더 가치 있게):\n- **개인과 상호작용** > 프로세스와 도구\n- **동작하는 SW** > 포괄적인 문서\n- **고객과의 협력** > 계약 협상\n- **변화에 대응** > 계획을 따르기\n### 다른 보기\n- 나머지 셋: 모두 좌우가 **뒤집혔어요.**" },
  { kind: "ox", id: "se-q-am-2", concept: "agile-manifesto", q: "애자일 선언문은 오른쪽 항목(프로세스, 문서, 계약, 계획)에 가치가 없다고 선언한다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n선언문은 오른쪽 항목에도 **가치가 있다**고 인정해요. 다만 **왼쪽을 더** 가치 있게 여길 뿐이에요." },
  { kind: "short", id: "se-q-am-3", concept: "agile-manifesto", q: "애자일 선언문: Working software over comprehensive ________. (영어 한 단어)", answers: ["documentation", "문서"], explain: "== 정답: documentation\n### 풀이\n\"Working software over comprehensive **documentation**\" — 포괄적인 **문서**보다 **동작하는 소프트웨어**를 더 가치 있게 여겨요." },
  { kind: "ox", id: "se-q-am-4", concept: "agile-manifesto", q: "애자일 선언문은 계획을 따르는 것보다 변화에 대응하는 것을 더 가치 있게 여긴다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n선언문의 네 번째 줄: **Responding to change over following a plan**(계획을 따르기보다 변화에 대응하기)." },

  // agile-principles
  { kind: "mc", id: "se-q-ap-1", concept: "agile-principles", q: "애자일 방법의 원칙이 아닌 것은?", options: ["Customer involvement", "Embrace change", "Maintain simplicity", "Comprehensive documentation"], answer: 3, explain: "== 정답: Comprehensive documentation\n### 왜 정답인가요\n애자일 5원칙: **고객 참여(Customer involvement)**, **점증적 인도(Incremental delivery)**, **변화 수용(Embrace change)**, **단순성 유지(Maintain simplicity)**, **프로세스가 아닌 사람(People not process)**. 포괄적 문서는 원칙이 아니에요." },
  { kind: "mc", id: "se-q-ap-2", concept: "agile-principles", q: "'팀의 기술을 인정·활용하고 규정된 프로세스 없이 자기 방식을 개발하게 한다'는 원칙은?", options: ["People not process", "Incremental delivery", "Embrace change", "Customer involvement"], answer: 0, explain: "== 정답: People not process\n### 왜 정답인가요\n**People not process(프로세스가 아닌 사람)**: 팀의 기술을 인정·활용하고, 정해진 프로세스 없이 **자기 방식**을 만들게 해요.\n### 다른 보기\n- Incremental delivery: 조금씩 인도하는 거예요.\n- Embrace change: 바뀔 걸 예상하고 수용하는 거예요.\n- Customer involvement: 고객이 개발에 참여하는 거예요." },
  { kind: "mc", id: "se-q-ap-3", concept: "agile-principles", q: "애자일이 잘 적용되는 경우는?", options: ["외부 규제가 많은 대형 시스템", "판매용 중소 규모 제품 개발", "고객이 참여를 거부하는 프로젝트", "수십 년 수명의 안전 필수 시스템"], answer: 1, explain: "== 정답: 판매용 중소 규모 제품 개발\n### 왜 정답인가요\n애자일은 ① **판매용 중소 규모 제품**, ② 고객 참여 약속이 있고 외부 규제가 적은 **사내 맞춤 시스템**에 잘 맞아요.\n### 다른 보기\n- 규제가 많은 대형 시스템, 고객이 참여를 거부, 수십 년 수명의 안전 필수 시스템: 계획 주도가 더 맞아요." },
  { kind: "ox", id: "se-q-ap-4", concept: "agile-principles", q: "조직 내 맞춤형 시스템에 애자일을 쓰려면 고객의 참여 약속이 있고 외부 규칙·규제가 적어야 한다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n사내 맞춤 시스템에 애자일을 쓰려면 **고객이 개발에 참여하겠다는 약속**이 있어야 하고, 문서를 많이 요구하는 **외부 규칙·규제가 적어야** 해요." },
  { kind: "ox", id: "se-q-ap-5", concept: "agile-principles", q: "'Embrace change'는 요구사항이 바뀌지 않도록 막는다는 뜻이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n**Embrace change**는 요구가 **바뀔 것을 예상하고**, 바뀌어도 수용할 수 있게 시스템을 설계한다는 뜻이에요. 막는 게 아니라 받아들이는 거예요." },

  // xp
  { kind: "mc", id: "se-q-xp-1", concept: "xp", q: "XP에서 증분을 고객에게 인도하는 주기는?", options: ["매일", "2주마다", "6개월마다", "1년마다"], answer: 1, explain: "== 정답: 2주마다\n### 풀이\nXP에서 새 버전은 **하루에도 여러 번** 빌드하고, 증분은 **대략 2주마다** 고객에게 인도해요." },
  { kind: "mc", id: "se-q-xp-2", concept: "xp", q: "'개발자 누구나 시스템의 어떤 코드든 바꿀 수 있다'는 XP 실천은?", options: ["Collective ownership", "Simple design", "Small releases", "Sustainable pace"], answer: 0, explain: "== 정답: Collective ownership\n### 왜 정답인가요\n**공동 소유권(collective ownership)**: 개발자 누구나 시스템의 **어떤 코드든** 바꿀 수 있어요(Anyone can change anything). 짝을 바꿔 가며 모두가 전체를 알게 돼요.\n### 다른 보기\n- Simple design: 현재 요구만큼만 설계해요.\n- Small releases: 작은 릴리스를 자주 해요.\n- Sustainable pace: 초과 근무를 피해요." },
  { kind: "mc", id: "se-q-xp-3", concept: "xp", q: "'과도한 초과 근무는 코드 품질과 중기 생산성을 떨어뜨리므로 허용하지 않는다'는 XP 실천은?", options: ["Sustainable pace", "On-site customer", "Pair programming", "Refactoring"], answer: 0, explain: "== 정답: Sustainable pace\n### 왜 정답인가요\n**지속 가능한 속도(sustainable pace)**: 과도한 초과 근무는 코드 품질과 중기 생산성을 떨어뜨리니 **허용하지 않아요.**\n### 다른 보기\n- On-site customer: 고객이 팀에 상주해요.\n- Pair programming: 둘이 함께 코딩해요.\n- Refactoring: 구조를 개선해요." },
  { kind: "mc", id: "se-q-xp-4", concept: "xp", q: "'태스크가 끝나는 즉시 전체 시스템에 통합하고, 이후 모든 단위 테스트를 통과해야 한다'는 실천은?", options: ["Continuous integration", "Incremental planning", "Simple design", "Collective ownership"], answer: 0, explain: "== 정답: Continuous integration\n### 왜 정답인가요\n**연속적 통합(continuous integration)**: 태스크가 끝나는 **즉시** 전체 시스템에 통합하고, 그 뒤 **모든 단위 테스트를 통과**해야 해요.\n### 다른 보기\n- Incremental planning: 스토리 카드로 계획해요.\n- Simple design, Collective ownership: 다른 실천이에요." },
  { kind: "ox", id: "se-q-xp-5", concept: "xp", q: "XP의 Simple design은 미래 요구까지 고려해 충분히 많은 설계를 미리 해 두는 것이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nXP의 **Simple design**은 **현재 요구를 만족할 만큼만** 설계하고 그 이상은 하지 않아요. 미래 변경은 예측할 수 없다고 보고 리팩토링으로 대응해요." },
  { kind: "ox", id: "se-q-xp-6", concept: "xp", q: "XP에서는 빌드마다 모든 테스트를 실행하고 테스트가 성공해야만 빌드를 수용한다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\nXP는 반복 개발을 '극단적'으로 해서, **빌드마다 모든 테스트**를 돌리고 **다 통과해야만** 빌드를 받아들여요." },
  { kind: "mc", id: "se-q-xp-7", concept: "xp", q: "XP의 On-site customer에 대한 설명으로 옳은 것은?", options: ["고객은 계약 때만 만난다", "최종 사용자 대표가 XP 팀에 풀타임으로 참여한다", "고객은 테스트에만 참여한다", "고객이 코드를 직접 짠다"], answer: 1, explain: "== 정답: 최종 사용자 대표가 XP 팀에 풀타임으로 참여한다\n### 왜 정답인가요\n**On-site customer**: 최종 사용자(고객) 대표가 XP 팀에 **풀타임**으로 들어와, 요구를 가져오고 바로 답해 줘요.\n### 다른 보기\n- 계약 때만, 테스트에만, 고객이 코드를 짬: 아니에요." },
  { kind: "ox", id: "se-q-xp-8", concept: "xp", q: "XP의 점진적 계획에서 요구사항은 상세한 요구사항 명세서(SRS)에 기록된다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nXP의 점진적 계획에서 요구는 상세한 SRS가 아니라 **스토리 카드**에 기록해요. 고객이 우선순위를 정해 릴리스에 넣을 스토리를 골라요." },

  // xp-agile-mapping
  { kind: "mc", id: "se-q-xm-1", concept: "xp-agile-mapping", q: "XP에서 '단순성 유지' 원칙을 지원하는 실천은?", options: ["지속적 리팩토링", "풀타임 고객", "정기 릴리스", "작은 릴리스"], answer: 0, explain: "== 정답: 지속적 리팩토링\n### 왜 정답인가요\nXP는 **코드를 계속 리팩토링**해서 **단순성을 유지**해요(Maintaining simplicity through constant refactoring).\n### 다른 보기\n- 풀타임 고객: 고객 참여 원칙을 지원해요.\n- 정기·작은 릴리스: 점증적 인도 원칙을 지원해요." },
  { kind: "ox", id: "se-q-xm-2", concept: "xp-agile-mapping", q: "XP는 원래 정의된 형태 그대로 대부분의 조직에서 널리 쓰인다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nXP는 **기술 중심**이라 조직의 관리 실천과 맞추기 어려워서, **원래 형태 그대로는 널리 쓰이지 않아요.** 대신 핵심 실천 몇 가지가 널리 퍼졌어요." },
  { kind: "mc", id: "se-q-xm-3", concept: "xp-agile-mapping", q: "널리 쓰이는 핵심 XP 실천이 아닌 것은?", options: ["사용자 스토리", "리팩토링", "테스트 우선 개발", "현장 고객 풀타임 상주"], answer: 3, explain: "== 정답: 현장 고객 풀타임 상주\n### 왜 정답인가요\n널리 쓰이는 핵심 XP 실천 4개: **사용자 스토리, 리팩토링, 테스트 우선 개발, 짝 프로그래밍**. 고객 풀타임 상주는 현실적으로 어려워 덜 쓰여요." },
  { kind: "ox", id: "se-q-xm-4", concept: "xp-agile-mapping", q: "'프로세스가 아닌 사람' 원칙은 짝 프로그래밍, 공동 소유권, 장시간 근무를 피하는 프로세스로 지원된다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n**People not process** 원칙은 **짝 프로그래밍**, **공동 소유권**, **장시간 근무를 피하는** 프로세스로 지원돼요." },

  // user-stories
  { kind: "mc", id: "se-q-us-1", concept: "user-stories", q: "XP에서 다음 릴리스에 넣을 스토리를 고르는 사람은?", options: ["개발자", "고객", "스크럼 마스터", "테스터"], answer: 1, explain: "== 정답: 고객\n### 왜 정답인가요\nXP에서 개발자는 스토리마다 일정을 **추정**하고, **고객**이 우선순위와 추정을 보고 다음 릴리스에 넣을 스토리를 **골라요.**\n### 다른 보기\n- 개발자: 추정만 해요.\n- 스크럼 마스터: 스크럼의 역할이에요.\n- 테스터: 고르는 사람이 아니에요." },
  { kind: "mc", id: "se-q-us-2", concept: "user-stories", q: "일정과 비용 추정의 기초가 되는 것은?", options: ["스토리 카드에서 분해한 구현 태스크", "애자일 선언문", "CMM 수준", "테스트 결과"], answer: 0, explain: "== 정답: 스토리 카드에서 분해한 구현 태스크\n### 왜 정답인가요\n스토리 카드를 **구현 태스크**로 쪼개면, 그 태스크들이 **일정과 비용 추정의 기초**가 돼요(These tasks are the basis of schedule and cost estimates).\n### 다른 보기\n- 애자일 선언문, CMM 수준, 테스트 결과: 추정의 기초가 아니에요." },
  { kind: "ox", id: "se-q-us-3", concept: "user-stories", q: "XP에서 사용자 요구사항은 사용자 스토리 또는 시나리오로 표현된다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\nXP에서 사용자 요구는 **사용자 스토리** 또는 **시나리오**로 표현하고, 카드에 적어 관리해요." },

  // refactoring
  { kind: "mc", id: "se-q-rf-1", concept: "refactoring", q: "XP가 '변경을 위한 설계'보다 리팩토링을 택하는 이유는?", options: ["변경을 믿을 만하게 예측할 수 없으므로", "설계가 너무 싸서", "리팩토링은 테스트가 필요 없어서", "문서가 많아져서"], answer: 0, explain: "== 정답: 변경을 믿을 만하게 예측할 수 없으므로\n### 왜 정답인가요\n전통적 SE는 미래 변경을 예상해 미리 설계하라고 하지만, XP는 **변경을 믿을 만하게 예측할 수 없어서** 그건 소용없다고 봐요. 대신 바뀔 때마다 **리팩토링**으로 대응해요.\n### 다른 보기\n- 설계가 싸서, 테스트가 필요 없어서, 문서가 많아져서: 이유가 아니에요." },
  { kind: "mc", id: "se-q-rf-2", concept: "refactoring", q: "리팩토링의 예가 아닌 것은?", options: ["중복 코드를 없애려 클래스 계층 재조직", "속성·메서드 정리와 이름 바꾸기", "인라인 코드를 라이브러리 메서드 호출로 교체", "새 기능 추가"], answer: 3, explain: "== 정답: 새 기능 추가\n### 왜 정답인가요\n리팩토링은 **기능은 그대로** 두고 **구조만** 개선하는 거예요. 새 기능 추가는 리팩토링이 아니에요.\n### 다른 보기\n- 클래스 계층 재조직, 이름 정리, 인라인 코드를 메서드 호출로: 모두 리팩토링 예예요." },
  { kind: "ox", id: "se-q-rf-3", concept: "refactoring", q: "리팩토링은 SW의 이해도를 높여 문서의 필요를 줄인다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n리팩토링으로 코드가 **읽기 쉬워지면**, 따로 설명할 **문서의 필요가 줄어요**(reduces the need for documentation)." },
  { kind: "ox", id: "se-q-rf-4", concept: "refactoring", q: "아키텍처 수준의 리팩토링은 코드 수준 리팩토링보다 훨씬 싸다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n아키텍처 수준 리팩토링은 시스템 전체 구조를 바꾸는 거라 코드 수준보다 **훨씬 비싸요.**" },
  { kind: "ox", id: "se-q-rf-5", concept: "refactoring", q: "XP에서는 당장 필요가 없어도 개선할 수 있는 곳을 찾으면 리팩토링한다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\nXP 팀은 **당장 필요가 없어도** 개선할 곳을 찾으면 리팩토링해요(even where there is no immediate need). 그래서 코드가 늘 바꾸기 쉬운 상태로 유지돼요." },

  // test-first
  { kind: "mc", id: "se-q-tf-1", concept: "test-first", q: "테스트 주도 개발에서 테스트를 작성하는 형태는?", options: ["종이에 적은 데이터", "자동 실행 가능한 프로그램", "구두 설명", "엑셀 표"], answer: 1, explain: "== 정답: 자동 실행 가능한 프로그램\n### 왜 정답인가요\n테스트 주도 개발에서 테스트는 데이터가 아니라 **프로그램**으로 작성해서 **자동으로** 실행해요(Tests are written as programs rather than data).\n### 다른 보기\n- 종이·구두·엑셀: 자동으로 실행할 수 없어요." },
  { kind: "short", id: "se-q-tf-2", concept: "test-first", q: "교안에서 예로 든 자동 테스트 프레임워크는? (영어)", answers: ["junit", "j unit"], explain: "== 정답: JUnit\n### 풀이\n교안의 자동 테스트 프레임워크 예는 **JUnit**(Java 단위 테스트)이에요. 테스트를 프로그램으로 써서 자동으로 돌려요.", hint: "영문" },
  { kind: "mc", id: "se-q-tf-3", concept: "test-first", q: "XP 테스트에서 고객의 역할은?", options: ["단위 테스트 코드 작성", "다음 릴리스 스토리의 인수 테스트 개발을 돕기", "테스트 자동화 도구 설치", "테스트 생략 결정"], answer: 1, explain: "== 정답: 다음 릴리스 스토리의 인수 테스트 개발을 돕기\n### 왜 정답인가요\nXP에서 고객은 다음 릴리스에 들어갈 스토리의 **인수 테스트(acceptance test)** 를 만드는 걸 도와요. 시스템이 고객이 원한 대로 동작하는지 확인하는 테스트예요.\n### 다른 보기\n- 단위 테스트 코드 작성: 개발자의 일이에요.\n- 도구 설치, 테스트 생략 결정: 고객의 역할이 아니에요." },
  { kind: "mc", id: "se-q-tf-4", concept: "test-first", q: "테스트 우선 개발의 문제점이 아닌 것은?", options: ["프로그래머가 테스트를 대충 쓴다", "복잡한 UI의 표시 로직은 점진적으로 테스트하기 어렵다", "테스트 집합의 완전성 판단이 어렵다", "요구사항이 더 모호해진다"], answer: 3, explain: "== 정답: 요구사항이 더 모호해진다\n### 왜 정답인가요\n테스트를 **먼저** 쓰면 무엇을 만들지 구체적으로 정해야 해서 요구가 오히려 **명확해져요.**\n### 다른 보기\n- 테스트를 대충 씀, 복잡한 UI 표시 로직은 점진적 테스트가 어려움, 테스트 집합의 완전성 판단이 어려움: 모두 교안이 든 문제점이에요." },
  { kind: "ox", id: "se-q-tf-5", concept: "test-first", q: "새 기능을 넣을 때는 새 테스트만 실행하고 이전 테스트는 실행하지 않는다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n새 기능을 넣으면 **이전 테스트와 새 테스트를 모두** 자동으로 돌려요. 새 코드가 예전 기능을 망가뜨리지 않았는지 확인해야 하니까요." },
  { kind: "ox", id: "se-q-tf-6", concept: "test-first", q: "시스템 테스트가 많으면 완전한 테스트 커버리지가 보장된다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n테스트가 **많아도** 모든 경우를 다룬다는 보장은 없어요. 테스트 개수와 **완전한 커버리지**는 다른 이야기예요." },

  // pair-programming
  { kind: "mc", id: "se-q-pp-1", concept: "pair-programming", q: "짝 프로그래밍의 이점이 아닌 것은?", options: ["코드 공동 소유와 지식 확산", "비공식 검토 역할", "리팩토링 장려", "항상 개발 인원을 절반으로 줄임"], answer: 3, explain: "== 정답: 항상 개발 인원을 절반으로 줄임\n### 왜 정답인가요\n짝 프로그래밍은 두 명이 한 컴퓨터로 일하는 거라 인원을 줄이지 않아요.\n### 다른 보기\n- 코드 공동 소유·지식 확산, 비공식 검토, 리팩토링 장려: 모두 이점이에요(팀원 이탈 위험 감소도)." },
  { kind: "ox", id: "se-q-pp-2", concept: "pair-programming", q: "짝 프로그래밍의 짝은 프로젝트 내내 고정된다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n짝은 **동적으로** 바뀌어서, 개발 중에 **모든 팀원이 서로 함께** 일하게 돼요. 그래서 지식이 팀 전체에 퍼져요." },
  { kind: "ox", id: "se-q-pp-3", concept: "pair-programming", q: "짝 프로그래밍의 지식 공유는 팀원이 떠날 때 프로젝트의 전체 위험을 줄인다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n여러 사람이 같은 코드를 알게 되니, 누가 **떠나도** 그 지식이 팀에 남아서 프로젝트 **위험이 줄어요.**" },
  { kind: "ox", id: "se-q-pp-4", concept: "pair-programming", q: "짝 프로그래밍은 항상 두 명이 따로 일하는 것보다 비효율적이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n짝 프로그래밍이 두 명이 따로 일하는 것만큼 **효율적이거나 더 낫다는** 근거도 있어요(경험 많은 사람끼리면 덜 효율적일 수 있다는 연구도 있어요). '항상 비효율'은 틀렸어요." },

  // agile-pm
  { kind: "mc", id: "se-q-pm2-1", concept: "agile-pm", q: "SW 프로젝트 관리자의 주된 책임은?", options: ["코드를 가장 많이 작성", "SW를 제때 계획된 예산 안에서 인도", "테스트를 생략", "고객과의 접촉 차단"], answer: 1, explain: "== 정답: SW를 제때 계획된 예산 안에서 인도\n### 왜 정답인가요\n프로젝트 관리자의 주된 책임은 SW를 **제때(on time)**, **계획된 예산 안에서(within budget)** 인도하는 거예요.\n### 다른 보기\n- 코드를 가장 많이 작성, 테스트 생략, 고객 접촉 차단: 관리자의 책임이 아니에요." },
  { kind: "ox", id: "se-q-pm2-2", concept: "agile-pm", q: "프로젝트 관리의 표준 접근은 애자일이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n프로젝트 관리의 **표준 접근은 계획 주도**예요. 애자일은 이걸 반복 개발에 맞게 바꾼 방식이에요." },

  // scrum
  { kind: "mc", id: "se-q-sc-1", concept: "scrum", q: "스크럼의 세 단계 순서로 옳은 것은?", options: ["개요 계획 → 스프린트 주기 → 프로젝트 종료", "스프린트 → 개요 계획 → 종료", "종료 → 계획 → 스프린트", "계획 → 종료 → 스프린트"], answer: 0, explain: "== 정답: 개요 계획 → 스프린트 주기 → 프로젝트 종료\n### 왜 정답인가요\n1. **개요 계획(outline planning)**: 목표와 SW 아키텍처를 설계\n2. **스프린트 주기(sprint cycles)**: 스프린트마다 증분 개발 반복\n3. **프로젝트 종료(project closure)**: 문서 완성, 교훈 평가" },
  { kind: "mc", id: "se-q-sc-2", concept: "scrum", q: "스크럼에 대한 설명으로 옳은 것은?", options: ["특정 코딩 실천을 규정한다", "반복 개발의 관리에 초점을 둔 프로젝트 관리 프레임워크다", "폭포수 모델의 일종이다", "문서 작성 방법론이다"], answer: 1, explain: "== 정답: 반복 개발의 관리에 초점을 둔 프로젝트 관리 프레임워크다\n### 왜 정답인가요\n스크럼은 특정 코딩 실천이 아니라 **반복 개발을 관리**하는 데 초점을 둔 **프로젝트 관리 프레임워크**예요.\n### 다른 보기\n- 코딩 실천 규정: XP 쪽이에요.\n- 폭포수의 일종, 문서 작성 방법론: 아니에요." },
  { kind: "mc", id: "se-q-sc-3", concept: "scrum", q: "스크럼의 프로젝트 종료 단계에서 하는 일이 아닌 것은?", options: ["사용자 매뉴얼 등 문서 완성", "교훈 평가", "SW 아키텍처 처음 설계", "프로젝트 마무리"], answer: 2, explain: "== 정답: SW 아키텍처 처음 설계\n### 왜 정답인가요\n아키텍처 설계는 **첫 단계(개요 계획)** 에서 해요. 프로젝트 종료 단계에서는 **문서(사용자 매뉴얼 등) 완성**, **교훈 평가**, 마무리를 해요." },
  { kind: "ox", id: "se-q-sc-4", concept: "scrum", q: "스크럼에서는 불안정한 요구사항이 진행을 막지 않는다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n스크럼은 스프린트마다 백로그를 다시 정하니, 요구가 **불안정해도 진행이 막히지 않아요**(Unstable requirements do not hold up progress)." },
  { kind: "mc", id: "se-q-sc-5", concept: "scrum", q: "스크럼의 이점이 아닌 것은?", options: ["제품을 관리 가능한 덩어리로 나눈다", "팀 전체가 모든 것을 볼 수 있다", "고객과 개발자 사이 신뢰가 생긴다", "상세한 사전 명세가 보장된다"], answer: 3, explain: "== 정답: 상세한 사전 명세가 보장된다\n### 왜 정답인가요\n스크럼은 상세 명세를 미리 다 만들지 않고 **백로그로 점진적으로** 정해요.\n### 다른 보기\n- 관리 가능한 덩어리로 나눔, 팀 전체가 모든 것을 봄, 고객-개발자 신뢰: 모두 스크럼의 이점이에요." },

  // scrum-terms
  { kind: "mc", id: "se-q-st-1", concept: "scrum-terms", q: "스크럼에서 스프린트의 일반적인 길이는?", options: ["1일", "2~4주", "6개월", "1년"], answer: 1, explain: "== 정답: 2~4주\n### 풀이\n스프린트는 보통 **2~4주**의 **고정된 길이**예요." },
  { kind: "short", id: "se-q-st-2", concept: "scrum-terms", q: "스크럼 개발팀은 최대 몇 명 이하여야 하는가?", answers: ["7", "7명"], explain: "== 정답: 7\n### 풀이\n스크럼 개발팀은 **7명 이하**의 자기 조직적 팀이에요. 작아야 소통이 잘 돼요.", hint: "숫자" },
  { kind: "mc", id: "se-q-st-3", concept: "scrum-terms", q: "'제품 기능·요구를 찾고 우선순위를 정하며 백로그를 계속 검토하는' 역할은?", options: ["Scrum Master", "Product owner", "Development team", "Stakeholder"], answer: 1, explain: "== 정답: Product owner\n### 왜 정답인가요\n**Product owner**는 제품 기능과 요구를 찾고, **우선순위**를 정하고, **백로그를 계속 검토**해요.\n### 다른 보기\n- Scrum Master: 프로세스를 지키게 돕고 팀을 외부 방해에서 보호해요.\n- Development team: 실제로 개발해요.\n- Stakeholder: 이해관계자예요." },
  { kind: "mc", id: "se-q-st-4", concept: "scrum-terms", q: "'한 스프린트에 처리할 수 있는 백로그 노력의 추정치'는?", options: ["Velocity", "Backlog", "Sprint", "Increment"], answer: 0, explain: "== 정답: Velocity\n### 왜 정답인가요\n**Velocity(속도)** = 팀이 **한 스프린트에 처리할 수 있는** 백로그 노력의 추정치예요. 다음 스프린트 계획에 써요.\n### 다른 보기\n- Backlog: 할 일 목록이에요.\n- Sprint: 개발 반복 단위예요.\n- Increment: 스프린트 결과물이에요." },
  { kind: "ox", id: "se-q-st-5", concept: "scrum-terms", q: "스크럼 마스터는 프로젝트 관리자와 같은 역할이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n스크럼 개발자들은 스크럼 마스터를 **프로젝트 관리자로 생각하면 안 된다**고 단호해요. 스크럼 마스터는 지시하는 사람이 아니라 **촉진자(facilitator)** 예요." },
  { kind: "mc", id: "se-q-st-6", concept: "scrum-terms", q: "'스크럼 팀이 처리해야 할 to do 항목 목록'은?", options: ["Product backlog", "Sprint review", "Velocity", "Scrum board"], answer: 0, explain: "== 정답: Product backlog\n### 왜 정답인가요\n**Product backlog** = 스크럼 팀이 처리해야 할 **'to do' 항목 목록**이에요(기능, 요구, 개선 등).\n### 다른 보기\n- Sprint review: 스프린트 끝 검토 회의예요.\n- Velocity: 처리 능력 추정이에요.\n- Scrum board: 진행 상황 판이에요." },
  { kind: "ox", id: "se-q-st-7", concept: "scrum-terms", q: "'Potentially shippable product increment'는 테스트 같은 추가 작업 없이 최종 제품에 넣을 수 있는 완성 상태를 뜻한다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n**Potentially shippable product increment**는 테스트 같은 추가 작업 없이 **바로 최종 제품에 넣을 수 있는** 완성 상태예요. 실제로는 늘 가능하지는 않아요." },
  { kind: "ox", id: "se-q-st-8", concept: "scrum-terms", q: "스크럼(Scrum)은 한 달에 한 번 여는 긴 정기 회의다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n스크럼(Scrum) 회의는 **매일** 여는 **짧은 대면 회의**(일일 스크럼)예요." },
  { kind: "ox", id: "se-q-st-9", concept: "scrum-terms", q: "Product owner는 반드시 개발팀 안의 개발자가 맡아야 한다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nProduct owner는 **고객**일 수도, SW 회사의 **제품 관리자**나 다른 **이해관계자 대표**일 수도 있어요. 개발자일 필요는 없어요." },

  // sprint-cycle
  { kind: "mc", id: "se-q-sp-1", concept: "sprint-cycle", q: "스프린트 개발 중 팀과 외부(고객·조직)의 소통은 누구를 거치는가?", options: ["Product owner", "Scrum master", "CEO", "고객 대표"], answer: 1, explain: "== 정답: Scrum master\n### 왜 정답인가요\n스프린트 개발 중 팀은 외부와 **격리**되고, 모든 외부 소통은 **스크럼 마스터**를 거쳐요. 스크럼 마스터가 팀을 외부 방해에서 **보호**해요.\n### 다른 보기\n- Product owner: 백로그와 우선순위를 맡아요.\n- CEO, 고객 대표: 직접 연락하지 않아요." },
  { kind: "mc", id: "se-q-sp-2", concept: "sprint-cycle", q: "스크럼 보드의 열 순서로 옳은 것은?", options: ["Story → To do → In progress → Testing → Done", "To do → Story → Done → Testing", "Done → Testing → To do", "In progress → Story → To do → Done"], answer: 0, explain: "== 정답: Story → To do → In progress → Testing → Done\n### 왜 정답인가요\n스크럼 보드는 작업이 흘러가는 순서대로 열이 있어요: **Story(백로그) → To do(할 일) → In progress(진행 중) → Testing(테스트) → Done(완료)**." },
  { kind: "mc", id: "se-q-sp-3", concept: "sprint-cycle", q: "일일 스크럼 회의에서 공유하지 않는 것은?", options: ["지난 회의 이후의 진척", "생긴 문제", "다음 날 계획", "개인 연봉 협상"], answer: 3, explain: "== 정답: 개인 연봉 협상\n### 왜 정답인가요\n일일 스크럼에서는 ① 지난 회의 이후 **진척**, ② 생긴 **문제**, ③ **다음 날 계획**을 공유해요. 연봉 협상은 관계없어요." },
  { kind: "ox", id: "se-q-sp-4", concept: "sprint-cycle", q: "스프린트 계획의 출발점은 제품 백로그다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n스프린트 계획은 **제품 백로그**에서 시작해요(The starting point for planning is the product backlog). 거기서 이번 스프린트에 할 항목을 골라요." },
  { kind: "ox", id: "se-q-sp-5", concept: "sprint-cycle", q: "스프린트에서 개발할 기능은 스크럼 마스터 혼자 선택한다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n스프린트에서 개발할 기능은 **프로젝트 팀 전체가 고객과 함께** 골라요. 스크럼 마스터 혼자 정하지 않아요." },
  { kind: "mc", id: "se-q-sp-6", concept: "sprint-cycle", q: "스크럼 마스터가 촉진자로서 하는 일이 아닌 것은?", options: ["일일 회의 준비", "백로그 추적", "결정 기록", "개발자에게 코딩 방식을 지시"], answer: 3, explain: "== 정답: 개발자에게 코딩 방식을 지시\n### 왜 정답인가요\n스크럼 마스터는 **촉진자**라 지시하지 않아요. 하는 일: **일일 회의 준비**, **백로그 추적**, **결정 기록**, **진척 측정**, **외부 소통**." },

  // scaling-agile
  { kind: "mc", id: "se-q-sa-1", concept: "scaling-agile", q: "'작은 팀으로 개발할 수 없는 대형 SW 시스템에 애자일을 쓰는 것'은?", options: ["Scaling up", "Scaling out", "Scaling down", "Scaling in"], answer: 0, explain: "== 정답: Scaling up\n### 왜 정답인가요\n**Scaling up**: 작은 팀으로는 못 만드는 **대형 시스템**에 애자일을 쓰는 거예요.\n### 다른 보기\n- Scaling out: **대형 조직** 전체에 애자일을 도입하는 거예요.\n- Scaling down/in: 교안 용어가 아니에요." },
  { kind: "mc", id: "se-q-sa-2", concept: "scaling-agile", q: "'오랜 개발 경험이 있는 대형 조직 전체에 애자일을 도입하는 것'은?", options: ["Scaling up", "Scaling out", "Refactoring", "Pair programming"], answer: 1, explain: "== 정답: Scaling out\n### 왜 정답인가요\n**Scaling out**: 오랜 개발 경험이 있는 **대형 조직 전체**에 애자일을 도입하는 거예요.\n### 다른 보기\n- Scaling up: 대형 **시스템**이에요.\n- Refactoring, Pair programming: XP 실천이에요." },
  { kind: "mc", id: "se-q-sa-3", concept: "scaling-agile", q: "애자일 계약 문제의 해법으로 교안이 제시한 것은?", options: ["기능이 아니라 개발자 시간에 대해 지불하는 계약", "모든 명세를 미리 고정한 계약", "계약 없이 진행", "고정 가격 계약"], answer: 0, explain: "== 정답: 기능이 아니라 개발자 시간에 대해 지불하는 계약\n### 왜 정답인가요\n애자일은 명세를 미리 다 정하지 않아서 '이 기능을 이 값에' 계약이 어려워요. 그래서 **개발자 시간**에 대해 돈을 내는 계약을 제안해요. 다만 법무팀은 이걸 **고위험**으로 봐요.\n### 다른 보기\n- 모든 명세를 미리 고정, 고정 가격: 애자일과 맞지 않아요.\n- 계약 없이: 현실적이지 않아요." },
  { kind: "ox", id: "se-q-sa-4", concept: "scaling-agile", q: "애자일은 신규 개발보다 유지보수에 더 적합하다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n애자일은 **신규 개발**에 더 맞게 만들어졌어요. 그런데 대기업 비용 대부분은 **유지보수**라서 그게 문제예요." },
  { kind: "mc", id: "se-q-sa-5", concept: "scaling-agile", q: "애자일을 확장할 때 지켜야 할 애자일 기본이 아닌 것은?", options: ["유연한 계획", "잦은 릴리스", "지속적 통합", "상세한 사전 설계 문서"], answer: 3, explain: "== 정답: 상세한 사전 설계 문서\n### 왜 정답인가요\n애자일을 확장해도 지켜야 할 기본: **유연한 계획, 잦은 릴리스, 지속적 통합, TDD, 좋은 팀 소통**. 상세한 사전 설계 문서는 애자일 기본이 아니에요." },
  { kind: "ox", id: "se-q-sa-6", concept: "scaling-agile", q: "애자일의 비공식성은 대기업이 흔히 쓰는 법적 계약 정의 방식과 잘 맞는다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n애자일의 **비공식성**은 대기업이 흔히 쓰는 **법적 계약** 정의 방식과 **잘 맞지 않아요.** 계약은 미리 정한 명세를 요구하니까요." },

  // agile-maintenance
  { kind: "mc", id: "se-q-ma-1", concept: "agile-maintenance", q: "애자일 유지보수의 핵심 문제가 아닌 것은?", options: ["제품 문서 부족", "고객 참여 유지", "개발팀 연속성 유지", "코드가 너무 길다"], answer: 3, explain: "== 정답: 코드가 너무 길다\n### 왜 정답인가요\n애자일 유지보수의 핵심 문제: ① **제품 문서 부족**(애자일은 문서가 적음), ② 개발 후 **고객 참여 유지**, ③ **개발팀 연속성** 유지." },
  { kind: "ox", id: "se-q-ma-2", concept: "agile-maintenance", q: "대부분의 조직은 신규 개발보다 기존 SW 유지보수에 더 많은 비용을 쓴다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n대부분의 조직은 **신규 개발보다 기존 SW 유지보수**에 더 많은 돈을 써요. 그래서 애자일이 성공하려면 유지보수도 지원해야 해요." },

  // agile-vs-plan-choice
  { kind: "mc", id: "se-q-vp-1", concept: "agile-vs-plan-choice", q: "구현 전에 매우 상세한 명세와 설계가 중요하다면 어떤 방식이 적합한가?", options: ["계획 주도", "애자일", "code-and-fix", "XP"], answer: 0, explain: "== 정답: 계획 주도\n### 왜 정답인가요\n구현 전에 **매우 상세한 명세와 설계**가 꼭 필요하다면 미리 다 계획하는 **계획 주도** 방식이 맞아요.\n### 다른 보기\n- 애자일, XP: 명세를 점진적으로 만들어요.\n- code-and-fix: 체계가 없어요." },
  { kind: "mc", id: "se-q-vp-2", concept: "agile-vs-plan-choice", q: "다음 중 계획 주도 쪽으로 기울게 하는 '시스템 이슈'는?", options: ["작은 co-located 팀", "외부 규제를 받는 시스템", "짧은 수명", "빠른 피드백이 가능"], answer: 1, explain: "== 정답: 외부 규제를 받는 시스템\n### 왜 정답인가요\n**외부 규제**를 받는 시스템은 규제 기관에 낼 **안전 사례(safety case)** 같은 **상세 문서**가 필요해서 계획 주도로 기울어요.\n### 다른 보기\n- 작은 co-located 팀, 짧은 수명, 빠른 피드백: 모두 **애자일** 쪽으로 기울어요." },
  { kind: "ox", id: "se-q-vp-3", concept: "agile-vs-plan-choice", q: "팀이 분산되어 있으면 설계 문서가 필요할 수 있다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n팀이 여러 곳에 **분산**돼 있으면 얼굴 보고 소통하기 어려워서, 서로 맞추기 위한 **설계 문서**가 필요할 수 있어요." },
  { kind: "ox", id: "se-q-vp-4", concept: "agile-vs-plan-choice", q: "수명이 긴 시스템일수록 문서가 덜 필요하다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n수명이 긴 시스템은 나중에 맡을 **지원팀**에 원래 개발자의 의도를 전해야 해서 **문서가 더 필요해요.**" },
  { kind: "mc", id: "se-q-vp-5", concept: "agile-vs-plan-choice", q: "'점증적 인도' 원칙이 조직 실천과 충돌하는 이유는?", options: ["마케팅·비즈니스의 장기 계획과 맞지 않을 수 있어서", "고객이 너무 많아서", "도구가 없어서", "테스트가 많아서"], answer: 0, explain: "== 정답: 마케팅·비즈니스의 장기 계획과 맞지 않을 수 있어서\n### 왜 정답인가요\n마케팅은 **몇 달 전에** 어떤 기능이 나올지 알아야 캠페인을 준비할 수 있어요. 그런데 점증적 인도는 무엇이 언제 나올지 미리 정하지 않아서 충돌해요.\n### 다른 보기\n- 고객이 많아서, 도구가 없어서, 테스트가 많아서: 이유가 아니에요." },
  { kind: "ox", id: "se-q-vp-6", concept: "agile-vs-plan-choice", q: "애자일이 계획 기반보다 더 높은 기술 수준을 요구한다는 주장이 있다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n계획 기반은 **상세 설계를 코드로 옮기기만** 하면 되지만, 애자일은 개발자가 설계까지 스스로 판단해야 해서 **더 높은 기술 수준**이 필요하다는 주장이 있어요." },

  // large-systems
  { kind: "mc", id: "se-q-ls-1", concept: "large-systems", q: "다중 팀 스크럼에서 '팀 대표들이 매일 모여 진척을 논의'하는 것은?", options: ["Scrum of Scrums", "Release alignment", "Role replication", "Sprint review"], answer: 0, explain: "== 정답: Scrum of Scrums\n### 왜 정답인가요\n**Scrum of Scrums**: 여러 팀의 **대표들이 매일 모여** 진척을 논의하고 조율해요.\n### 다른 보기\n- Release alignment: 팀들의 릴리스 날짜를 맞추는 거예요.\n- Role replication: 팀마다 PO·SM을 두는 거예요.\n- Sprint review: 스프린트 끝 검토예요." },
  { kind: "mc", id: "se-q-ls-2", concept: "large-systems", q: "다중 팀 스크럼의 요소가 아닌 것은?", options: ["Role replication", "Product architects", "Release alignment", "Single global scrum master"], answer: 3, explain: "== 정답: Single global scrum master\n### 왜 정답인가요\n다중 팀 스크럼은 **팀마다** Product owner와 Scrum master를 둬요(**Role replication**). 전체에 하나뿐인 스크럼 마스터는 요소가 아니에요.\n### 다른 보기\n- Role replication, Product architects(팀마다 아키텍트), Release alignment: 모두 다중 팀 스크럼 요소예요(+ Scrum of Scrums)." },
  { kind: "ox", id: "se-q-ls-3", concept: "large-systems", q: "대형 시스템은 이해관계자가 다양해 모두를 개발에 참여시키기가 사실상 불가능하다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n대형 시스템은 **이해관계자가 매우 다양**해서(diverse set of stakeholders) 모두를 개발에 참여시키는 게 사실상 불가능해요." },
  { kind: "ox", id: "se-q-ls-4", concept: "large-systems", q: "대형 시스템은 개발 기간이 짧아 일관된 팀을 유지하기 쉽다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n대형 시스템은 조달·개발 기간이 **길어서** 그동안 사람이 바뀌니 **일관된 팀을 유지하기 어려워요.**" },

  // why-devops
  { kind: "mc", id: "se-q-wd-1", concept: "why-devops", q: "DevOps가 연결하는 세 가지는?", options: ["개발, 운영, 사용자 피드백", "설계, 코딩, 문서", "고객, 법무, 마케팅", "HW, SW, 네트워크"], answer: 0, explain: "== 정답: 개발, 운영, 사용자 피드백\n### 왜 정답인가요\nDevOps는 **개발(Dev)**, **운영(Ops)**, **사용자 피드백**을 하나로 이어요.\n### 다른 보기\n- 설계·코딩·문서, 고객·법무·마케팅, HW·SW·네트워크: DevOps의 연결 대상이 아니에요." },
  { kind: "mc", id: "se-q-wd-2", concept: "why-devops", q: "DevOps가 기반으로 하는 방법은?", options: ["폭포수와 V 모델", "애자일과 린", "CMM과 PMBOK", "COTS와 재사용"], answer: 1, explain: "== 정답: 애자일과 린\n### 왜 정답인가요\nDevOps는 **애자일(Agile)** 과 **린(Lean)** 방법을 기반으로 해요.\n### 다른 보기\n- 폭포수·V 모델: 계획 주도예요.\n- CMM·PMBOK: 성숙도·관리 지식 체계예요.\n- COTS·재사용: 재사용 SE예요." },
  { kind: "mc", id: "se-q-wd-3", concept: "why-devops", q: "DevOps를 '문화 운동(cultural movement)'으로 정의한 출처는?", options: ["Wikipedia", "IBM", "O'Reilly", "IEEE"], answer: 2, explain: "== 정답: O'Reilly\n### 왜 정답인가요\n**O'Reilly**는 DevOps를 **문화 운동(cultural movement)** 으로 정의했어요.\n### 다른 보기\n- Wikipedia, IBM: 개발·운영의 **통합·자동화** 관점이에요.\n- IEEE: **원칙과 실천** 관점이에요." },
  { kind: "ox", id: "se-q-wd-4", concept: "why-devops", q: "사일로 기반 개발은 각 단계 사이의 상호작용이 활발하다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n**사일로 기반** 개발은 각 단계(팀)가 **따로 놀아서 상호작용이 없어요.** 그게 문제라서 DevOps가 나왔어요." },
  { kind: "ox", id: "se-q-wd-5", concept: "why-devops", q: "24시간 고객 서비스를 제공하는 Amazon, Google, Netflix 같은 조직이 DevOps를 적용했다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n**24시간 서비스**를 제공하는 Amazon, Google, Netflix 같은 조직이 DevOps를 적용했어요. 멈추지 않고 자주 배포해야 하니까요." },

  // lean
  { kind: "short", id: "se-q-ln-1", concept: "lean", q: "린 SW 개발의 슬로건: Think Big, Act Small, Fail Fast, Learn ______. (영어 한 단어)", answers: ["rapidly", "빠르게"], explain: "== 정답: rapidly\n### 풀이\n린 SW 개발 슬로건: **Think Big, Act Small, Fail Fast, Learn Rapidly**(크게 생각하고, 작게 행동하고, 빨리 실패하고, 빨리 배워라).", hint: "영문" },
  { kind: "mc", id: "se-q-ln-2", concept: "lean", q: "린 SW 개발의 7원칙이 아닌 것은?", options: ["낭비를 제거하라", "최대한 늦게 결정하라", "최대한 빨리 배포하라", "최대한 빨리 결정하라"], answer: 3, explain: "== 정답: 최대한 빨리 결정하라\n### 왜 정답인가요\n린 원칙은 정보가 충분히 모일 때까지 **최대한 늦게 결정하라**예요. 빨리 결정하는 건 반대예요.\n### 다른 보기\n- 낭비 제거, 최대한 늦게 결정, 최대한 빨리 배포: 모두 린 7원칙에 있어요." },
  { kind: "ox", id: "se-q-ln-3", concept: "lean", q: "린 개발은 소프트웨어 개발에서 처음 시작해 나중에 제조업으로 퍼졌다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n거꾸로예요. 린은 **제조업**(도요타)에서 처음 시작됐고, 지금은 관리·UX·스타트업·**SW 개발**로 퍼졌어요." },
  { kind: "ox", id: "se-q-ln-4", concept: "lean", q: "린 SW 개발은 기능을 늘려 가치를 만드는 방식을 최적화한다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n린은 기능을 늘리는 게 아니라 **낭비를 줄여** 가치를 만드는 방식을 최적화해요." },

  // devops-principles
  { kind: "mc", id: "se-q-dp-1", concept: "devops-principles", q: "CI/CD 파이프라인의 핵심 요소이며 사람의 실수를 줄이는 DevOps 원칙은?", options: ["Automation", "Collaboration", "Customer-centric action", "Create with end in mind"], answer: 0, explain: "== 정답: Automation\n### 왜 정답인가요\n**자동화(Automation)** 는 **CI/CD 파이프라인**의 핵심이고, 사람 손을 줄여 **실수를 줄여요.**\n### 다른 보기\n- Collaboration: 팀 간 협업이에요.\n- Customer-centric action: 고객 중심 행동이에요.\n- Create with end in mind: 끝(사용자)을 생각하며 만들기예요." },
  { kind: "mc", id: "se-q-dp-2", concept: "devops-principles", q: "'거품 속에서 만들지 말라(don't build in a bubble)'는 DevOps 원칙은?", options: ["Continuous improvement", "Create with end in mind", "Automation", "Collaboration"], answer: 1, explain: "== 정답: Create with end in mind\n### 왜 정답인가요\n**Create with end in mind**: 실제 고객이 무엇을 원하는지 이해하고 만들라, **거품 속에서(가정에 기반해) 만들지 말라**는 원칙이에요.\n### 다른 보기\n- Continuous improvement: 계속 개선하기예요.\n- Automation, Collaboration: 다른 원칙이에요." },
  { kind: "mc", id: "se-q-dp-3", concept: "devops-principles", q: "Improvement Kata와 관련된 DevOps 원칙은?", options: ["Continuous improvement", "Customer-centric action", "Collaboration", "Automation"], answer: 0, explain: "== 정답: Continuous improvement\n### 왜 정답인가요\n**지속적 개선(Continuous improvement)** 은 애자일, 린 제조, **Improvement Kata**의 기본이에요.\n### 다른 보기\n- Customer-centric action, Collaboration, Automation: 다른 원칙이에요." },
  { kind: "short", id: "se-q-dp-4", concept: "devops-principles", q: "CI/CD에서 CI의 풀네임은? (영어)", answers: ["continuous integration", "지속적 통합"], explain: "== 정답: Continuous integration\n### 풀이\n**CI = Continuous Integration(지속적 통합)**, **CD = Continuous Delivery(지속적 인도)** 예요." },
  { kind: "ox", id: "se-q-dp-5", concept: "devops-principles", q: "DevOps에서는 개발팀과 운영팀이 하나의 팀으로 합쳐지기도 한다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\nDevOps에서는 개발팀과 운영팀이 협업을 넘어 **하나의 팀으로 합쳐지기도** 해요(Often… merge into a single team)." },
  { kind: "ox", id: "se-q-dp-6", concept: "devops-principles", q: "고객 중심 행동 원칙은 긴 피드백 루프를 통해 신중하게 대응하는 것이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n고객 중심 행동은 **짧은 피드백 루프**, **실시간 모니터링**, **빠른 배포**로 고객에게 빨리 대응하는 거예요." },

  // devops-benefits
  { kind: "short", id: "se-q-db-1", concept: "devops-benefits", q: "DORA 2019 보고서에 따르면 엘리트 팀은 저성과 팀보다 몇 배 더 자주 배포하는가?", answers: ["208", "208배"], explain: "== 정답: 208\n### 풀이\nDORA 2019 보고서: 엘리트 팀은 저성과 팀보다 **208배 더 자주**, **106배 더 빠르게** 배포해요.", hint: "숫자" },
  { kind: "short", id: "se-q-db-2", concept: "devops-benefits", q: "'Mean Time to Recovery'의 약어는? (영문 4자)", answers: ["mttr"], explain: "== 정답: MTTR\n### 풀이\n**MTTR = Mean Time to Recovery(평균 복구 시간)**. 장애가 나서 복구하기까지 걸리는 평균 시간이에요.", hint: "영문" },
  { kind: "mc", id: "se-q-db-3", concept: "devops-benefits", q: "DevOps의 이점이 아닌 것은?", options: ["협업과 신뢰", "더 빠른 릴리스", "문제 해결 시간 단축", "운영팀의 완전한 제거"], answer: 3, explain: "== 정답: 운영팀의 완전한 제거\n### 왜 정답인가요\nDevOps는 운영팀을 없애는 게 아니라 개발과 **함께 일하게** 해요.\n### 다른 보기\n- 협업과 신뢰, 더 빠른 릴리스, 문제 해결 시간 단축: 모두 이점이에요(+ 계획되지 않은 업무 관리)." },
  { kind: "ox", id: "se-q-db-4", concept: "devops-benefits", q: "DORA 2019 보고서에서 엘리트 팀은 저성과 팀보다 106배 더 빠르게 배포한다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\nDORA 2019: 엘리트 팀은 **208배 더 자주**, **106배 더 빠르게** 배포해요." },

  // devops-process
  { kind: "mc", id: "se-q-dv-1", concept: "devops-process", q: "DevOps 프로세스의 순서로 옳은 것은?", options: ["Plan → Code → Build → Test → Release → Deploy → Operate → Monitor", "Code → Plan → Test → Build → Deploy → Release → Monitor → Operate", "Plan → Build → Code → Release → Test → Monitor → Deploy → Operate", "Monitor → Operate → Deploy → Release → Test → Build → Code → Plan"], answer: 0, explain: "== 정답: Plan → Code → Build → Test → Release → Deploy → Operate → Monitor\n### 왜 정답인가요\n**Dev 쪽**: Plan(계획) → Code(코딩) → Build(빌드) → Test(테스트) / **Ops 쪽**: Release(릴리스 준비) → Deploy(배포) → Operate(운영) → Monitor(모니터링). 무한 루프(∞) 모양으로 다시 Plan으로 이어져요." },
  { kind: "mc", id: "se-q-dv-2", concept: "devops-process", q: "Infrastructure as Code, 보안 문제, 로그 관리를 다루는 단계는?", options: ["Build", "Release", "Operate", "Plan"], answer: 2, explain: "== 정답: Operate\n### 왜 정답인가요\n**Operate(운영·인프라 구성)** 단계에서 **Infrastructure as Code**, 보안 문제, **로그 관리**를 다뤄요.\n### 다른 보기\n- Build: 코드를 빌드해요.\n- Release: 배포 준비가 된 상태예요.\n- Plan: 사용자 스토리로 계획해요." },
  { kind: "mc", id: "se-q-dv-3", concept: "devops-process", q: "'코드가 지속적 통합 테스트를 통과해 배포 준비가 된' 단계는?", options: ["Release", "Deploy", "Monitor", "Code"], answer: 0, explain: "== 정답: Release\n### 왜 정답인가요\n**Release**: 코드가 **지속적 통합 테스트를 통과**해서 **배포 준비**가 된 단계예요.\n### 다른 보기\n- Deploy: 실제로 운영 환경에 내보내요.\n- Monitor: 운영 상태를 지켜봐요.\n- Code: 코드를 작성해요." },
  { kind: "mc", id: "se-q-dv-4", concept: "devops-process", q: "DevOps 프로세스 중 Ops에 속하지 않는 것은?", options: ["Release", "Deploy", "Monitor", "Build"], answer: 3, explain: "== 정답: Build\n### 왜 정답인가요\n**Build**는 **Dev** 쪽(Plan·Code·Build·Test)이에요.\n### 다른 보기\n- Release, Deploy, Monitor: 모두 **Ops** 쪽(Release·Deploy·Operate·Monitor)이에요." },
  { kind: "ox", id: "se-q-dv-5", concept: "devops-process", q: "DevOps의 Plan 단계에서는 애자일의 사용자 스토리로 태스크를 계획한다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\nDevOps의 **Plan** 단계는 애자일의 **사용자 스토리** 방식으로 태스크를 계획해요." },
  { kind: "ox", id: "se-q-dv-6", concept: "devops-process", q: "DevOps에서는 개발팀과 운영팀이 서로 다른 코드 도구를 쓰는 것이 중요하다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nDevOps에선 개발팀과 운영팀이 **GitHub·GitLab 같은 도구를 공유**하는 게 중요해요. 서로 다른 도구를 쓰면 다시 사일로가 돼요." },
  { kind: "mc", id: "se-q-dv-7", concept: "devops-process", q: "교안에서 말하는 '완벽한 사용자 스토리'의 구성 요소가 아닌 것은?", options: ["what (who, where, trigger)", "why", "acceptance criteria", "how much salary"], answer: 3, explain: "== 정답: how much salary\n### 왜 정답인가요\n완벽한 사용자 스토리 = **what**(누가, 어디서, 무엇이 계기로) + **why**(왜 필요한지) + **acceptance criteria**(인수 기준). 급여는 관계없어요." },

  // devops-toolchain-metrics
  { kind: "mc", id: "se-q-dt-1", concept: "devops-toolchain-metrics", q: "DevOps 툴체인의 설명으로 옳은 것은?", options: ["한 벤더의 단일 도구", "여러 벤더의 도구가 통합된 하나처럼 동작하는 도구 모음", "하드웨어 장비", "문서 템플릿"], answer: 1, explain: "== 정답: 여러 벤더의 도구가 통합된 하나처럼 동작하는 도구 모음\n### 왜 정답인가요\n**DevOps 툴체인**은 여러 회사의 도구(Git, Jenkins, Docker…)를 묶어 **하나처럼** 쓰는 도구 모음이에요.\n### 다른 보기\n- 한 벤더의 단일 도구, 하드웨어 장비, 문서 템플릿: 툴체인의 정의가 아니에요." },
  { kind: "mc", id: "se-q-dt-2", concept: "devops-toolchain-metrics", q: "DevOps 성과 측정 지표가 아닌 것은?", options: ["배포 주기", "MTTD", "가용성", "개발자 수면 시간"], answer: 3, explain: "== 정답: 개발자 수면 시간\n### 왜 정답인가요\nDevOps 성과 지표: **배포 주기·규모·시간**, 리드 타임, 고객 불만, 자동 테스트 성공률, **가용성**, SLA, **MTTD**, MTTR 등. 수면 시간은 지표가 아니에요." },
  { kind: "short", id: "se-q-dt-3", concept: "devops-toolchain-metrics", q: "'Mean Time to Detection'의 약어는? (영문 4자)", answers: ["mttd"], explain: "== 정답: MTTD\n### 풀이\n**MTTD = Mean Time to Detection**, 결함을 **발견**하기까지의 평균 시간이에요. (복구는 MTTR)", hint: "영문" },
  { kind: "ox", id: "se-q-dt-4", concept: "devops-toolchain-metrics", q: "서비스 수준 협약(SLA)은 DevOps 성과 측정 지표에 포함된다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n**SLA(서비스 수준 협약)** 를 지키는지도 DevOps 성과 측정 지표 목록에 있어요." },

  // devops-vs-agile
  { kind: "mc", id: "se-q-da-1", concept: "devops-vs-agile", q: "DevOps와 Agile의 차이로 옳은 것은?", options: ["Agile은 운영팀을 포함한다", "DevOps는 운영팀을 포함하고 인도·유지보수까지 확장한다", "DevOps는 계획된 작업만 다룬다", "Agile은 테스트 자동화에만 집중한다"], answer: 1, explain: "== 정답: DevOps는 운영팀을 포함하고 인도·유지보수까지 확장한다\n### 왜 정답인가요\n애자일은 주로 **개발**에 초점을 두지만, DevOps는 **운영팀까지 포함**해서 **인도와 유지보수**까지 관심을 넓혀요.\n### 다른 보기\n- Agile이 운영팀 포함: 반대예요.\n- DevOps는 계획된 작업만: 계획되지 않은 운영 작업도 다뤄요.\n- Agile은 테스트 자동화에만: 아니에요." },
  { kind: "ox", id: "se-q-da-2", concept: "devops-vs-agile", q: "애자일과 DevOps의 궁극적 목표는 서로 다르다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n애자일과 DevOps의 궁극적 목표는 **같아요**: SW 개발의 **속도와 품질** 향상. 다루는 범위가 다를 뿐이에요." },
  { kind: "ox", id: "se-q-da-3", concept: "devops-vs-agile", q: "DevOps는 운영팀에 흔한 계획되지 않은 작업까지 포함한다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n운영팀에는 장애 대응처럼 **계획되지 않은 작업**이 흔해요. DevOps는 이런 작업까지 포함해요." },
  { kind: "mc", id: "se-q-da-4", concept: "devops-vs-agile", q: "Agile이 강조하고 DevOps가 '테스트와 인도 자동화'로 확장한 것은?", options: ["반복 개발과 작은 배치", "계약 협상", "포괄적 문서", "폭포수 단계"], answer: 0, explain: "== 정답: 반복 개발과 작은 배치\n### 왜 정답인가요\n애자일은 **반복 개발과 작은 배치**를 강조하고, DevOps는 이를 **테스트와 인도 자동화**로 확장해요.\n### 다른 보기\n- 계약 협상, 포괄적 문서, 폭포수 단계: 애자일이 강조하지 않아요." },

  // sw-pm
  { kind: "mc", id: "se-q-sm-1", concept: "sw-pm", q: "SW 프로젝트의 성공 기준이 아닌 것은?", options: ["합의한 시간에 인도", "예산 안의 비용", "고객 기대 만족", "가능한 많은 코드 줄 수"], answer: 3, explain: "== 정답: 가능한 많은 코드 줄 수\n### 왜 정답인가요\n프로젝트 성공 기준: ① **합의한 시간에 인도**, ② **예산 안의 비용**, ③ **고객 기대 만족**, ④ **일관되고 잘 돌아가는 팀 유지**. 코드 줄 수는 기준이 아니에요." },
  { kind: "ox", id: "se-q-sm-2", concept: "sw-pm", q: "SW 개발은 늘 예산과 일정 제약을 받기 때문에 프로젝트 관리가 필요하다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\nSW 개발은 늘 **예산과 일정 제약**을 받아요. 그 안에서 끝내려면 프로젝트 관리가 필요해요." },
  { kind: "mc", id: "se-q-sm-3", concept: "sw-pm", q: "프로젝트 관리에 영향을 주는 요소가 아닌 것은?", options: ["회사 규모", "SW 유형", "조직 문화", "관리자의 키"], answer: 3, explain: "== 정답: 관리자의 키\n### 왜 정답인가요\n프로젝트 관리에 영향을 주는 요소: **회사 규모**, SW 고객, SW 규모, **SW 유형**, **조직 문화**, SW 개발 프로세스. 관리자의 키는 관계없어요." },

  // sw-mgmt-distinctions
  { kind: "mc", id: "se-q-md-1", concept: "sw-mgmt-distinctions", q: "SW 관리의 특수성이 아닌 것은?", options: ["제품이 무형이다", "많은 프로젝트가 일회성이다", "프로세스가 가변적이고 조직마다 다르다", "진척을 눈으로 쉽게 볼 수 있다"], answer: 3, explain: "== 정답: 진척을 눈으로 쉽게 볼 수 있다\n### 왜 정답인가요\nSW는 **무형**이라 건물처럼 진척이 **눈에 보이지 않아요.** 그래서 관리가 어려워요.\n### 다른 보기\n- 제품이 무형, 프로젝트가 일회성, 프로세스가 가변적·조직마다 다름: 모두 SW 관리의 특수성이에요." },
  { kind: "ox", id: "se-q-md-2", concept: "sw-mgmt-distinctions", q: "SW 프로세스는 전통 공학 프로세스만큼 성숙하다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nSW 프로세스는 다리·건물을 짓는 **전통 공학 프로세스만큼 성숙하지 않아요.** 그래서 일정·비용 예측이 더 어려워요." },
  { kind: "ox", id: "se-q-md-3", concept: "sw-mgmt-distinctions", q: "경험이 많은 관리자라도 새 대형 프로젝트의 문제를 예상하기 어려울 수 있다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n대형 SW 프로젝트는 대부분 **일회성(one-off)** 이라 이전 경험이 그대로 통하지 않아요. 그래서 경험 많은 관리자도 문제를 예상하기 어려워요." },

  // mgmt-activities
  { kind: "mc", id: "se-q-ma2-1", concept: "mgmt-activities", q: "'일을 수주하려고 프로젝트 목표와 수행 방법을 기술하는' 관리 활동은?", options: ["Reporting", "Proposal writing", "Risk management", "People management"], answer: 1, explain: "== 정답: Proposal writing\n### 왜 정답인가요\n**제안서 작성(proposal writing)** 은 일을 따내려고 프로젝트 **목표와 수행 방법**을 적는 활동이에요. 보통 비용·일정 추정도 들어가요.\n### 다른 보기\n- Reporting: 진척을 보고해요.\n- Risk management: 위험을 다뤄요.\n- People management: 팀원을 관리해요." },
  { kind: "mc", id: "se-q-ma2-2", concept: "mgmt-activities", q: "보편적인 관리 활동이 아닌 것은?", options: ["Project planning", "Risk management", "Reporting", "Code compiling"], answer: 3, explain: "== 정답: Code compiling\n### 왜 정답인가요\n보편적 관리 활동: **프로젝트 계획, 위험 관리, 사람 관리, 보고, 제안서 작성**. 코드 컴파일은 개발 작업이에요." },
  { kind: "ox", id: "se-q-ma2-3", concept: "mgmt-activities", q: "프로젝트 관리자는 고객과 회사 관리자에게 프로젝트 진척을 보고할 책임이 있다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n**보고(reporting)**: 프로젝트 관리자는 **고객과 회사 관리자**에게 진척을 알려야 해요." },

  // risk-mgmt
  { kind: "mc", id: "se-q-rm-1", concept: "risk-mgmt", q: "'일정이나 자원'에 영향을 주는 위험은?", options: ["프로젝트 위험", "제품 위험", "비즈니스 위험", "기술 위험"], answer: 0, explain: "== 정답: 프로젝트 위험\n### 왜 정답인가요\n위험 3분류:\n- **프로젝트 위험**: **일정이나 자원**에 영향\n- **제품 위험**: 개발 중인 SW의 **품질·성능**에 영향\n- **비즈니스 위험**: SW를 만들거나 사는 **조직**에 영향" },
  { kind: "mc", id: "se-q-rm-2", concept: "risk-mgmt", q: "'경쟁 제품이 먼저 출시되는 것'은 어떤 위험인가?", options: ["프로젝트", "제품", "비즈니스", "사람"], answer: 2, explain: "== 정답: 비즈니스\n### 왜 정답인가요\n경쟁 제품이 먼저 나오면 우리 제품을 만드는 **조직의 사업**이 타격을 받으니 **비즈니스 위험**이에요.\n### 다른 보기\n- 프로젝트: 일정·자원 쪽이에요.\n- 제품: SW 품질·성능 쪽이에요." },
  { kind: "mc", id: "se-q-rm-3", concept: "risk-mgmt", q: "'CASE 도구가 기대만큼 동작하지 않는 것'은 어떤 위험인가?", options: ["프로젝트", "제품", "비즈니스", "조직"], answer: 1, explain: "== 정답: 제품\n### 왜 정답인가요\nCASE 도구가 기대만큼 안 되면 만들어지는 **SW의 품질**에 영향을 주니 **제품 위험**이에요." },
  { kind: "mc", id: "se-q-rm-4", concept: "risk-mgmt", q: "'경험 많은 인력이 프로젝트가 끝나기 전에 떠나는 것(Staff turnover)'은?", options: ["프로젝트 위험", "제품 위험", "비즈니스 위험", "기술 위험"], answer: 0, explain: "== 정답: 프로젝트 위험\n### 왜 정답인가요\n경험 많은 사람이 떠나면 **인력(자원)과 일정**에 영향을 주니 **프로젝트 위험**이에요." },
  { kind: "ox", id: "se-q-rm-5", concept: "risk-mgmt", q: "요구사항 변경은 프로젝트와 제품 모두에 영향을 주는 위험이다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n요구가 바뀌면 다시 해야 할 일이 생겨 **일정(프로젝트)** 에도, 만드는 **SW 자체(제품)** 에도 영향을 줘요. 그래서 **프로젝트와 제품** 위험이에요." },
  { kind: "ox", id: "se-q-rm-6", concept: "risk-mgmt", q: "기반 기술이 새 기술로 대체되는 것(Technology change)은 프로젝트 위험이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n기반 기술이 새 기술로 대체되면 제품이 시장에서 뒤처져 조직 사업에 영향을 주니 **비즈니스 위험**이에요." },
  { kind: "mc", id: "se-q-rm-7", concept: "risk-mgmt", q: "SW 개발의 불확실성 원인으로 교안에 든 것이 아닌 것은?", options: ["느슨하게 정의된 요구사항", "고객 요구 변화로 인한 요구 변경", "시간과 자원 추정의 어려움", "컴퓨터 전원 전압"], answer: 3, explain: "== 정답: 컴퓨터 전원 전압\n### 왜 정답인가요\nSW 개발의 불확실성 원인: **느슨한 요구 정의**, 고객 요구 변화에 따른 **요구 변경**, 시간·자원 **추정의 어려움**, **개인 기술 차이**. 전원 전압은 관계없어요." },

  // risk-process
  { kind: "mc", id: "se-q-rp-1", concept: "risk-process", q: "위험 관리 프로세스의 순서로 옳은 것은?", options: ["식별 → 분석 → 계획 → 감시", "분석 → 식별 → 감시 → 계획", "계획 → 식별 → 분석 → 감시", "감시 → 계획 → 분석 → 식별"], answer: 0, explain: "== 정답: 식별 → 분석 → 계획 → 감시\n### 왜 정답인가요\n1. **식별**: 어떤 위험이 있나 찾고\n2. **분석**: 확률과 영향을 평가하고\n3. **계획**: 피하거나 줄이거나 대비할 계획을 세우고\n4. **감시**: 계속 지켜보며 재평가해요.\n찾아야 분석하고, 분석해야 계획할 수 있어요." },
  { kind: "mc", id: "se-q-rp-2", concept: "risk-process", q: "위험 분석에서 결과(effects)의 등급이 아닌 것은?", options: ["Catastrophic", "Serious", "Tolerable", "Excellent"], answer: 3, explain: "== 정답: Excellent\n### 왜 정답인가요\n결과(영향) 등급: **Catastrophic(재앙적), Serious(심각), Tolerable(견딜 만함), Insignificant(무시할 만함)**. Excellent는 없어요." },
  { kind: "ox", id: "se-q-rp-3", concept: "risk-process", q: "위험 식별에는 흔한 위험의 체크리스트를 쓸 수 있다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n위험 식별 때 흔한 위험을 모아 둔 **체크리스트**를 쓸 수 있어요. 팀 활동이나 관리자 경험으로도 찾아요." },
  { kind: "ox", id: "se-q-rp-4", concept: "risk-process", q: "위험 감시는 프로젝트 시작 때 한 번만 하면 된다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n위험은 프로젝트 내내 바뀌어서 **정기적으로 재평가**해야 하고, 핵심 위험은 **진척 회의**마다 논의해요." },
  { kind: "mc", id: "se-q-rp-5", concept: "risk-process", q: "교안의 위험 분석 표에서 '필요한 기술의 인력을 채용할 수 없음'의 확률과 영향은?", options: ["Low / Catastrophic", "High / Catastrophic", "Moderate / Serious", "High / Tolerable"], answer: 1, explain: "== 정답: High / Catastrophic\n### 풀이\n교안 표 (3) \"필요한 기술의 인력을 채용할 수 없음\" → 확률 **High**, 영향 **Catastrophic**." },
  { kind: "mc", id: "se-q-rp-6", concept: "risk-process", q: "교안의 위험 분석 표에서 '조직 재정 문제로 예산 삭감'의 확률과 영향은?", options: ["Low / Catastrophic", "High / Serious", "Moderate / Tolerable", "High / Catastrophic"], answer: 0, explain: "== 정답: Low / Catastrophic\n### 풀이\n교안 표 (7) \"조직 재정 문제로 예산 삭감\" → 확률은 **Low**지만 일어나면 **Catastrophic**이에요." },
  { kind: "mc", id: "se-q-rp-7", concept: "risk-process", q: "교안 표에서 '코드 생성 도구가 만든 코드가 비효율적'의 영향 등급은?", options: ["Catastrophic", "Serious", "Tolerable", "Insignificant"], answer: 3, explain: "== 정답: Insignificant\n### 풀이\n교안 표 \"코드 생성 도구가 만든 코드가 비효율적\" → 확률 Moderate, 영향 **Insignificant**. 조금 느린 코드는 큰 문제가 아니라서예요." },

  // risk-types
  { kind: "mc", id: "se-q-rt-1", concept: "risk-types", q: "'핵심 인력이 결정적 시기에 아파서 없다'는 어떤 위험 유형인가?", options: ["People", "Technology", "Estimation", "Tools"], answer: 0, explain: "== 정답: People\n### 왜 정답인가요\n**People(사람)** 위험: 필요한 인력 채용 불가, **핵심 인력이 아파서 없음**, 필요한 교육 부족.\n### 다른 보기\n- Technology: DB 성능, 재사용 컴포넌트 결함이에요.\n- Estimation: 시간·크기 과소 추정이에요.\n- Tools: 도구 문제예요." },
  { kind: "mc", id: "se-q-rt-2", concept: "risk-types", q: "'DB가 기대한 초당 트랜잭션을 처리하지 못한다'는 어떤 위험 유형인가?", options: ["Requirements", "Technology", "Organizational", "People"], answer: 1, explain: "== 정답: Technology\n### 왜 정답인가요\nDB가 기대한 성능(초당 트랜잭션)을 못 내는 건 **Technology(기술)** 위험이에요. 재사용 컴포넌트의 결함도 기술 위험이에요.\n### 다른 보기\n- Requirements, Organizational, People: 다른 유형이에요." },
  { kind: "mc", id: "se-q-rt-3", concept: "risk-types", q: "'SW 크기를 과소 추정했다'는 어떤 위험 유형인가?", options: ["Estimation", "Tools", "Technology", "People"], answer: 0, explain: "== 정답: Estimation\n### 왜 정답인가요\nSW 크기, 개발 시간, 결함 수정 속도를 **과소 추정**한 건 **Estimation(추정)** 위험이에요." },
  { kind: "mc", id: "se-q-rt-4", concept: "risk-types", q: "'조직이 개편되어 다른 경영진이 프로젝트를 맡는다'는 어떤 위험 유형인가?", options: ["Organizational", "People", "Requirements", "Tools"], answer: 0, explain: "== 정답: Organizational\n### 왜 정답인가요\n**조직 개편**으로 다른 경영진이 맡거나, 조직 **재정 문제**는 **Organizational(조직)** 위험이에요." },
  { kind: "ox", id: "se-q-rt-5", concept: "risk-types", q: "'SW 도구들이 통합되어 동작하지 않는다'는 Technology 위험이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nSW 도구들이 서로 통합되지 않는 건 **Tools(도구)** 위험이에요. **Technology** 위험은 DB 성능, 재사용 컴포넌트 결함 같은 거예요." },
  { kind: "ox", id: "se-q-rt-6", concept: "risk-types", q: "'고객이 요구 변경의 영향을 이해하지 못한다'는 People 위험이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n고객이 요구 변경의 영향을 이해하지 못하는 건 **Requirements(요구사항)** 위험이에요." },

  // risk-strategies
  { kind: "mc", id: "se-q-rs-1", concept: "risk-strategies", q: "위험이 일어날 '확률'을 줄이는 전략은?", options: ["Avoidance strategies", "Minimization strategies", "Contingency plans", "Monitoring"], answer: 0, explain: "== 정답: Avoidance strategies\n### 왜 정답인가요\n**회피 전략**은 위험이 일어날 **확률**을 줄여요.\n### 다른 보기\n- Minimization: 일어났을 때 **영향**을 줄여요.\n- Contingency plans: 일어났을 때 **대처**해요.\n- Monitoring: 위험을 지켜보는 단계예요." },
  { kind: "mc", id: "se-q-rs-2", concept: "risk-strategies", q: "위험이 일어났을 때 대처하는 계획은?", options: ["회피 전략", "최소화 전략", "비상 계획(Contingency plans)", "위험 식별"], answer: 2, explain: "== 정답: 비상 계획(Contingency plans)\n### 왜 정답인가요\n**비상 계획**은 위험이 **이미 일어났을 때** 어떻게 대처할지 준비해 둔 계획이에요.\n### 다른 보기\n- 회피: 확률을 줄여요.\n- 최소화: 영향을 줄여요.\n- 위험 식별: 위험을 찾는 단계예요." },
  { kind: "mc", id: "se-q-rs-3", concept: "risk-strategies", q: "'인력 질병' 위험에 대한 교안의 전략은?", options: ["고객에게 지연 가능성을 알림", "업무가 겹치도록 팀을 재조직해 서로의 일을 이해하게 함", "더 빠른 DB 구매", "경영진 보고서 준비"], answer: 1, explain: "== 정답: 업무가 겹치도록 팀을 재조직해 서로의 일을 이해하게 함\n### 왜 정답인가요\n누가 아파도 다른 사람이 그 일을 이어받을 수 있게 **업무가 겹치도록** 팀을 재조직해요(최소화 전략).\n### 다른 보기\n- 고객에게 지연 알림, 더 빠른 DB 구매, 경영진 보고서 준비: 다른 위험의 전략이에요." },
  { kind: "mc", id: "se-q-rs-4", concept: "risk-strategies", q: "'요구사항 변경' 위험에 대한 교안의 전략은?", options: ["추적성 정보로 변경 영향을 평가하고 설계에서 정보 은닉을 최대화", "요구사항을 무시", "팀원 교체", "예산 증액 요청"], answer: 0, explain: "== 정답: 추적성 정보로 변경 영향을 평가하고 설계에서 정보 은닉을 최대화\n### 왜 정답인가요\n요구 변경 위험엔 ① **추적성 정보**로 어떤 부분이 영향을 받는지 평가하고, ② 설계에서 **정보 은닉**을 최대화해서 변경이 퍼지지 않게 해요.\n### 다른 보기\n- 무시, 팀원 교체, 예산 증액: 교안의 전략이 아니에요." },
  { kind: "mc", id: "se-q-rs-5", concept: "risk-strategies", q: "위험 지표에서 '조직 내 소문, 경영진의 무대응'은 어떤 위험 유형의 지표인가?", options: ["Organizational", "People", "Tools", "Estimation"], answer: 0, explain: "== 정답: Organizational\n### 왜 정답인가요\n**조직 내 소문**, **경영진의 무대응**은 **조직** 위험의 지표예요.\n### 다른 보기\n- People: 낮은 사기, 나쁜 관계, 높은 이직이에요.\n- Tools: 팀원이 도구를 꺼림 등이에요.\n- Estimation: 일정을 못 맞춤 등이에요." },
  { kind: "mc", id: "se-q-rs-6", concept: "risk-strategies", q: "위험 지표에서 '낮은 사기, 나쁜 팀 관계, 높은 이직'은 어떤 유형인가?", options: ["People", "Technology", "Requirements", "Estimation"], answer: 0, explain: "== 정답: People\n### 왜 정답인가요\n**낮은 사기, 나쁜 팀 관계, 높은 이직**은 **사람** 위험의 지표예요." },
  { kind: "ox", id: "se-q-rs-7", concept: "risk-strategies", q: "최소화 전략은 위험이 일어날 확률을 줄이는 것이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n확률을 줄이는 건 **회피** 전략이에요. **최소화** 전략은 위험의 **영향**을 줄여요." },
  { kind: "ox", id: "se-q-rs-8", concept: "risk-strategies", q: "What-if 질문은 위험 감시 단계에서만 쓰는 도구다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nWhat-if 질문(\"만약 ~하면?\")은 대비책을 세우는 **위험 계획** 단계에서 써요." },
  { kind: "short", id: "se-q-rs-9", concept: "risk-strategies", q: "교안의 What-if 질문: 경기 침체로 프로젝트 예산이 몇 % 삭감되면? (숫자만)", answers: ["20", "20%"], explain: "== 정답: 20\n### 풀이\n교안의 What-if 질문: \"What if an economic downturn leads to budget cuts of **20%**?\"(경기 침체로 예산이 20% 삭감되면?)", hint: "숫자" },

  // people-mgmt
  { kind: "mc", id: "se-q-pe-1", concept: "people-mgmt", q: "사람 관리의 요소가 아닌 것은?", options: ["Consistency", "Respect", "Inclusion", "Competition"], answer: 3, explain: "== 정답: Competition\n### 왜 정답인가요\n사람 관리의 4요소: **일관성(Consistency), 존중(Respect), 포용(Inclusion), 정직(Honesty)**. 경쟁은 요소가 아니에요." },
  { kind: "mc", id: "se-q-pe-2", concept: "people-mgmt", q: "'편애나 차별 없이 팀원 모두를 비슷하게 대우한다'는 요소는?", options: ["Consistency", "Respect", "Inclusion", "Honesty"], answer: 0, explain: "== 정답: Consistency\n### 왜 정답인가요\n**일관성(consistency)**: 편애나 차별 없이 팀원 **모두를 비슷하게** 대우해요.\n### 다른 보기\n- Respect: 사람마다 다른 기술을 존중해요.\n- Inclusion: 모두의 의견을 고려해요.\n- Honesty: 늘 솔직해요." },
  { kind: "ox", id: "se-q-pe-3", concept: "people-mgmt", q: "잘못된 사람 관리는 프로젝트 실패의 중요한 원인이다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n교안: **잘못된 사람 관리**는 프로젝트 실패의 **중요한 원인**이에요." },
  { kind: "ox", id: "se-q-pe-4", concept: "people-mgmt", q: "관리자는 프로젝트가 잘 안 될 때 팀의 사기를 위해 사실을 숨기는 것이 좋다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n**정직(Honesty)** 원칙: 관리자는 잘 되는 것과 **안 되는 것**을 늘 솔직하게 말해야 해요. 숨기면 신뢰를 잃어요." },

  // motivation
  { kind: "mc", id: "se-q-mo-1", concept: "motivation", q: "SW 개발 그룹에서 '자아실현(Self-realization)' 욕구를 채우는 방법은?", options: ["공동 시설 제공", "성취 인정", "교육과 책임", "식사 제공"], answer: 2, explain: "== 정답: 교육과 책임\n### 왜 정답인가요\n**자아실현** 욕구는 성장하는 느낌으로 채워져요. 그래서 **교육**(배울 기회)과 **책임**(맡는 일)이에요.\n### 다른 보기\n- 공동 시설, 비공식 소통: **사회적** 욕구예요.\n- 성취 인정: **존중** 욕구예요.\n- 식사 제공: 생리적 욕구예요." },
  { kind: "mc", id: "se-q-mo-2", concept: "motivation", q: "'존중(Esteem)' 욕구를 채우는 방법은?", options: ["성취 인정과 적절한 보상", "교육", "비공식 소통 허용", "안전한 건물"], answer: 0, explain: "== 정답: 성취 인정과 적절한 보상\n### 왜 정답인가요\n**존중(esteem)** 욕구는 **성취를 인정**받고 **적절한 보상**을 받을 때 채워져요.\n### 다른 보기\n- 교육: 자아실현이에요.\n- 비공식 소통: 사회적 욕구예요.\n- 안전한 건물: 안전 욕구예요." },
  { kind: "ox", id: "se-q-mo-3", concept: "motivation", q: "SW 개발 그룹에서 관리자가 가장 먼저 챙겨야 할 것은 생리적·안전 욕구다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nSW 개발 그룹에서 생리·안전 욕구는 이미 채워져 있어서 **문제가 아니에요.** 관리자는 **사회적·존중·자아실현** 욕구를 챙겨야 해요." },
  { kind: "mc", id: "se-q-mo-4", concept: "motivation", q: "교안 사례에서 의욕을 잃은 Dorothy에게 Alice가 한 조치는?", options: ["해고", "설계 자율권을 더 주고 SW 공학 교육 과정을 마련", "급여 삭감", "다른 팀으로 즉시 이동"], answer: 1, explain: "== 정답: 설계 자율권을 더 주고 SW 공학 교육 과정을 마련\n### 왜 정답인가요\nAlice는 Dorothy에게 **설계 자율권**을 더 주고 **SW 공학 교육 과정**을 마련해 줬어요. 존중과 자아실현 욕구를 채워 동기를 되살린 거예요.\n### 다른 보기\n- 해고, 급여 삭감, 즉시 이동: 사례의 조치가 아니에요." },
  { kind: "ox", id: "se-q-mo-5", concept: "motivation", q: "사례에서 Dorothy가 의욕을 잃은 이유는 C 프로그래밍이 너무 쉬워서였다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nDorothy는 **하드웨어 인터페이스 기술**을 쓰고 키울 기회가 없어서 의욕을 잃었어요. C 프로그래밍이 쉬워서가 아니에요." },
  { kind: "mc", id: "se-q-mo-6", concept: "motivation", q: "동기의 종류로 교안에 든 것이 아닌 것은?", options: ["기본 욕구", "개인 욕구", "사회적 욕구", "기계적 욕구"], answer: 3, explain: "== 정답: 기계적 욕구\n### 왜 정답인가요\n동기의 종류: **기본 욕구**(음식·수면), **개인 욕구**(존중·자존감), **사회적 욕구**(집단의 일원). 기계적 욕구는 없어요." },

  // personality-types
  { kind: "mc", id: "se-q-pt3-1", concept: "personality-types", q: "'일이 개인 목표(부자, 테니스, 여행)를 이루는 수단'인 성격 유형은?", options: ["Task-oriented", "Interaction-oriented", "Self-oriented", "Team-oriented"], answer: 2, explain: "== 정답: Self-oriented\n### 왜 정답인가요\n**자기 지향(self-oriented)**: 일은 개인 목표(부자, 테니스, 여행)를 이루는 **수단**이에요.\n### 다른 보기\n- Task-oriented: **일 자체**가 동기예요.\n- Interaction-oriented: **동료**가 동기예요.\n- Team/Goal-oriented: 교안의 세 유형이 아니에요." },
  { kind: "mc", id: "se-q-pt3-2", concept: "personality-types", q: "'동료의 존재와 행동이 주된 동기'인 유형은?", options: ["Task-oriented", "Interaction-oriented", "Self-oriented", "Goal-oriented"], answer: 1, explain: "== 정답: Interaction-oriented\n### 왜 정답인가요\n**상호작용 지향**: 동료의 존재와 행동이 주된 동기라, 함께 일하는 게 좋아서 출근해요.\n### 다른 보기\n- Task-oriented: 일 자체가 동기예요.\n- Self-oriented: 개인 목표가 동기예요." },
  { kind: "ox", id: "se-q-pt3-3", concept: "personality-types", q: "개인의 동기는 세 유형의 요소가 섞여 있고, 그 균형은 상황에 따라 바뀔 수 있다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n사람의 동기는 세 유형이 **섞여** 있고, 그 **균형은 상황에 따라** 바뀌어요(예: 아이가 생기면 자기 지향이 커질 수 있어요)." },
  { kind: "ox", id: "se-q-pt3-4", concept: "personality-types", q: "욕구 단계 이론만으로 실제 동기를 정확히 설명할 수 있다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n욕구 단계 이론은 **지나친 단순화**예요. 실제 동기를 이해하려면 **성격 유형**(과업·자기·상호작용 지향)도 고려해야 해요." },

  // group-cohesiveness
  { kind: "mc", id: "se-q-gc-1", concept: "group-cohesiveness", q: "응집력 있는 그룹의 장점이 아닌 것은?", options: ["그룹 품질 표준을 스스로 만든다", "지식이 공유된다", "리팩토링과 지속적 개선이 장려된다", "구성원이 떠나면 일이 완전히 멈춘다"], answer: 3, explain: "== 정답: 구성원이 떠나면 일이 완전히 멈춘다\n### 왜 정답인가요\n응집력 있는 그룹은 **지식이 공유**돼서 누가 떠나도 일이 **이어져요.** 멈추는 건 반대예요.\n### 다른 보기\n- 품질 표준을 스스로 만듦, 지식 공유, 리팩토링·지속적 개선 장려: 모두 장점이에요." },
  { kind: "mc", id: "se-q-gc-2", concept: "group-cohesiveness", q: "팀의 효과성에 영향을 주는 3요인이 아닌 것은?", options: ["그룹의 사람들", "그룹 조직", "기술·관리 의사소통", "사무실 층수"], answer: 3, explain: "== 정답: 사무실 층수\n### 왜 정답인가요\n팀 효과성의 3요인: ① **그룹의 사람들**, ② **그룹 조직**, ③ **기술·관리 의사소통**. 사무실 층수는 관계없어요." },
  { kind: "ox", id: "se-q-gc-3", concept: "group-cohesiveness", q: "응집력 있는 그룹에서는 구성원이 그룹을 어느 개인보다 중요하게 여긴다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n응집력 있는 그룹에선 구성원이 **그룹을 어느 개인보다 중요하게** 여겨요. 그래서 서로 돕고 책임을 나눠요." },
  { kind: "mc", id: "se-q-gc-4", concept: "group-cohesiveness", q: "교안 사례에서 Alice가 응집력을 키우려고 한 일이 아닌 것은?", options: ["월례 점심", "이틀짜리 away day 기술 업데이트", "가족 중 노인과 기술 이야기", "개인별 성과 순위 공개"], answer: 3, explain: "== 정답: 개인별 성과 순위 공개\n### 왜 정답인가요\nAlice는 **노인 가족과 기술 이야기**를 나누게 하고, **월례 점심**과 이틀짜리 **away day 기술 업데이트**를 열었어요. 성과 순위 공개는 경쟁을 부추겨 응집력을 해쳐요." },

  // group-composition
  { kind: "mc", id: "se-q-gp-1", concept: "group-composition", q: "모두 자기 지향(self-oriented)인 그룹에서 생기는 문제는?", options: ["모두 자기 일만 한다", "모두 보스가 되려 한다", "잡담만 많다", "문제가 없다"], answer: 1, explain: "== 정답: 모두 보스가 되려 한다\n### 왜 정답인가요\n자기 지향인 사람만 모이면 저마다 자기 목표를 앞세워 **모두 리더가 되려 해서** 갈등이 생겨요.\n### 다른 보기\n- 모두 자기 일만 함: 과업 지향만 모였을 때예요.\n- 잡담만 많음: 상호작용 지향만 모였을 때예요." },
  { kind: "mc", id: "se-q-gp-2", concept: "group-composition", q: "긴장을 감지하고 풀어 주어 매우 중요한 유형은?", options: ["Task-oriented", "Interaction-oriented", "Self-oriented", "없음"], answer: 1, explain: "== 정답: Interaction-oriented\n### 왜 정답인가요\n**상호작용 지향**인 사람은 팀 안의 **긴장을 감지하고 풀어 줘요.** 그래서 그룹에 매우 중요해요." },
  { kind: "ox", id: "se-q-gp-3", concept: "group-composition", q: "SW 엔지니어는 주로 상호작용 지향이라 그룹의 균형을 맞추기 쉽다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\nSW 엔지니어는 주로 **과업 지향**이라, 상호작용 지향을 섞어 그룹 **균형을 맞추기 어려워요.**" },
  { kind: "ox", id: "se-q-gp-4", concept: "group-composition", q: "효과적인 그룹은 세 성격 유형의 균형을 이룬다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n효과적인 그룹은 **과업·자기·상호작용 지향**이 고르게 섞여 있어요(An effective group has a balance of all types)." },
  { kind: "mc", id: "se-q-gp-5", concept: "group-composition", q: "이상적인 사람을 팀에 배정하지 못하는 이유로 교안에 든 것이 아닌 것은?", options: ["예산이 고액 인력을 허용하지 않음", "적절한 경험자가 없음", "조직이 직원 기술을 키우려 함", "모든 지원자가 과잉 자격"], answer: 3, explain: "== 정답: 모든 지원자가 과잉 자격\n### 왜 정답인가요\n이상적인 사람을 못 쓰는 이유 3개: ① **예산**이 고액 인력을 허용하지 않음, ② 적절한 **경험자가 없음**, ③ 조직이 **직원 기술을 키우려** 함." },
  { kind: "mc", id: "se-q-gp-6", concept: "group-composition", q: "교안 사례에서 Alice는 자신을 어떤 유형으로 판단했나?", options: ["과업 지향", "상호작용 지향", "자기 지향", "판단하지 않음"], answer: 2, explain: "== 정답: 자기 지향\n### 왜 정답인가요\nAlice는 이 프로젝트를 **경영진에게 주목받고 승진할 기회**로 봐서 자신을 **자기 지향**으로 판단했어요." },

  // group-org-comm
  { kind: "mc", id: "se-q-go-1", concept: "group-org-comm", q: "그룹 의사소통에 대한 설명으로 옳은 것은?", options: ["그룹이 클수록 소통이 쉽다", "비공식 구조가 계층 구조보다 소통이 낫다", "같은 성격 유형만 있을 때 소통이 낫다", "물리적 환경은 영향이 없다"], answer: 1, explain: "== 정답: 비공식 구조가 계층 구조보다 소통이 낫다\n### 왜 정답인가요\n**비공식 구조** 그룹이 **계층 구조**보다 소통이 더 잘 돼요. 위계를 거치지 않고 바로 이야기하니까요.\n### 다른 보기\n- 클수록 소통이 쉬움: 커질수록 어려워요.\n- 같은 성격만: 다양한 성격이 섞일 때 더 나아요.\n- 물리적 환경은 영향 없음: 영향이 있어요." },
  { kind: "mc", id: "se-q-go-2", concept: "group-org-comm", q: "비공식 그룹에서 그룹 리더의 역할은?", options: ["작업을 하나씩 배정한다", "외부 인터페이스 역할을 하지만 특정 작업을 배정하지 않는다", "모든 결정을 혼자 내린다", "코드만 작성한다"], answer: 1, explain: "== 정답: 외부 인터페이스 역할을 하지만 특정 작업을 배정하지 않는다\n### 왜 정답인가요\n비공식 그룹의 리더는 **외부와의 창구** 역할만 하고, 작업은 그룹이 함께 정해요. 리더가 하나하나 배정하지 않아요.\n### 다른 보기\n- 작업을 하나씩 배정, 모든 결정을 혼자: 계층 구조의 리더예요.\n- 코드만 작성: 리더 역할이 아니에요." },
  { kind: "ox", id: "se-q-go-3", concept: "group-org-comm", q: "애자일 개발은 공식 구조가 정보 교환을 막는다는 원칙에 따라 늘 비공식 그룹을 기반으로 한다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n애자일은 \"**공식 구조가 정보 교환을 막는다**\"는 원칙에 따라 늘 **비공식 그룹**을 기반으로 해요." },
  { kind: "ox", id: "se-q-go-4", concept: "group-org-comm", q: "비공식 그룹은 경험이 적은 신입 위주의 그룹에서 특히 성공적이다.", answer: false, explain: "== 정답: X (틀린 말)\n### 왜 틀렸나요\n비공식 그룹은 구성원이 **모두 경험 많고 유능할 때** 성공적이에요. 신입 위주면 방향을 잡아 줄 구조가 필요해요." },
  { kind: "ox", id: "se-q-go-5", concept: "group-org-comm", q: "그룹에 다른 성격 유형이 섞여 있고 혼성일 때 의사소통이 더 낫다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n그룹 구성: **다양한 성격 유형**이 섞이고 **혼성**일 때 의사소통이 더 잘 돼요." },

  // team-org-types
  { kind: "mc", id: "se-q-to-1", concept: "team-org-types", q: "'의사소통 경로가 짧아 인력과 진척 관리가 효율적인' 조직은?", options: ["직능별 조직", "프로젝트별 조직", "매트릭스 조직", "계층 조직"], answer: 1, explain: "== 정답: 프로젝트별 조직\n### 왜 정답인가요\n**프로젝트별 조직**은 한 프로젝트에 필요한 사람이 한 팀에 모여서 **의사소통 경로가 짧고**, 인력과 진척을 관리하기 효율적이에요.\n### 다른 보기\n- 직능별 조직: 부서 간 협업이라 경로가 길어요.\n- 매트릭스 조직: 여러 프로젝트에 중복 소속돼요.\n- 계층 조직: 교안 분류가 아니에요." },
  { kind: "mc", id: "se-q-to-2", concept: "team-org-types", q: "'구성원이 여러 프로젝트 팀에 중복으로 소속될 수 있는' 조직은?", options: ["매트릭스 조직", "프로젝트별 조직", "애자일 조직", "직능별 조직"], answer: 0, explain: "== 정답: 매트릭스 조직\n### 왜 정답인가요\n**매트릭스 조직**은 구성원이 **기능 팀에 소속**된 채 **여러 프로젝트 팀에 중복**으로 참여할 수 있어요.\n### 다른 보기\n- 프로젝트별 조직: 한 프로젝트에 전념해요.\n- 애자일 조직: 5~9명 팀이 함께 일해요.\n- 직능별 조직: 부서별로 역할을 나눠요." },
  { kind: "short", id: "se-q-to-3", concept: "team-org-types", q: "교안의 애자일 조직은 몇 명 정도의 팀인가? (예: 3-5)", answers: ["5-9", "5~9", "5~9명", "5-9명"], explain: "== 정답: 5~9\n### 풀이\n교안의 애자일 조직은 **5~9명**이 긴밀히 일하며 결과와 문제를 **공동 소유**해요.", hint: "a-b" },
  { kind: "ox", id: "se-q-to-4", concept: "team-org-types", q: "직능별 조직에서는 부서마다 같은 프로젝트에서 다른 역할을 하고 부서 간에 협업한다.", answer: true, explain: "== 정답: O (맞는 말)\n### 왜 그런가요\n**직능별 조직**은 분석·설계·구현·테스트처럼 **부서마다 역할**을 나누고, 같은 프로젝트에서 **부서끼리 협업**해요." },
];
